package com.shoply.infrastructure.web.controller;
import com.shoply.application.dto.AuthTokenDto; import com.shoply.application.service.AuthService; import com.shoply.infrastructure.web.request.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService auth){this.auth=auth;}@PostMapping("/register") ResponseEntity<AuthTokenDto> register(@Valid @RequestBody RegisterRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(auth.register(request.email(),request.password()));}@PostMapping("/login") AuthTokenDto login(@Valid @RequestBody LoginRequest request){return auth.login(request.email(),request.password());}}
